-- The Storm King's Vengeance (12919), Zul'Drak. The quest ran on a gossip option that did nothing: Gymer (29647) had a
-- stray row copied from the Frostborn Scout (credit for 12864 on gossip menu 9843), no Gymer vehicle script, no
-- bosses and none of the 193 Scourge of the phased event.
--
-- Gymer's option 2 makes the player cast Summon Gymer (55568 -> 55431); the summon spell already seats the player in
-- the vehicle (29884, spellclick spell 55430, which also carries the phase aura). Phases here replace the default
-- phase and a passenger does not take the phase of its vehicle, so the script gives the passenger phase 177 on boarding
-- and takes it away when the passenger leaves (the vehicle despawns 5 seconds later). All event spawns use phase 177.
-- Thrym is summoned by Prince Navarius' death, so he gets no static spawn. Gymer's options 1 and 2 were also missing
-- the "quest taken" condition option 0 has.

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (29821, 29872, 29884, 29895);

DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (29647, 29821, 29872, 29884, 29895);

DELETE FROM `creature_text` WHERE `entry` IN (29647, 29821, 29884, 29895);

DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 15 AND `SourceGroup` = 9852 AND `SourceEntry` IN (1, 2);

-- Phased spawns: Prince Navarius, Algar the Chosen (patrols a loop, path = guid) and the Scourge of the Dead Fields.
DELETE FROM `creature` WHERE `guid` BETWEEN 8326700 AND 8326899;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 8326700 AND 8326899;
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 8326700 AND 8326899;


